/* OrderCommonCsMapper.selectOrderList : Order List(Detail) */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT ad.LAST_POD_STATUS ,od.OD_JOB_NO ,od.CUST_CODE_LV1 AS UPPER_CUS_CODE ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) AS UPPER_CUS_NAME ,od.CUST_CODE_LV2 AS LOW_CUS_CODE ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) AS LOW_CUS_NAME ,od.PO_DATE ,od.PO_NO ,od.HBL_NO ,od.MBL_NO ,od.MASTER_OD_JOB_NO ,od.PIECES ,od.GWT ,od.OB_DATE ,od.AR_DATE ,od.INSPECTION_YN ,ad.SE_INSPECTION_YN ,ad.DROP_YN ,ad.XRAY_YN ,od.BOUND ,od.BOUND_TYPE ,CASE WHEN od.INSPECTION_YN = 'Y' THEN '검사' WHEN ad.SE_INSPECTION_YN = 'Y' THEN '선별' WHEN ad.XRAY_YN = 'Y' THEN 'XRAY' WHEN ad.DROP_YN = 'Y' THEN '취하' WHEN ad.CRIME_SELECTION_YN = 'Y' THEN '우범화물' WHEN od.INSPECTION_TYPE IS NOT NULL THEN '검역' END AS INSPECTION_GUBN ,(SELECT CONCAT(CODE, '.', NAME_${userLanguage}) FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'SE_INSPECTION_CODE' AND CODE = ad.SE_INSPECTION_CODE) AS SE_INSPECTION_CODE_NAME ,(SELECT CONCAT(CODE, '.', NAME_${userLanguage}) FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = ad.INSPECTION_APP_CODE AND GROUP_CODE = 'SE_INSPECTION_CODE') AS INSPECTION_APP_CODE ,CASE WHEN ISNULL(ad.SIMPLE_STATEMENT_YN,'') = 'N' THEN '' ELSE ISNULL(ad.SIMPLE_STATEMENT_YN,'') END AS SIMPLE_STATEMENT_YN ,CASE WHEN ISNULL(ad.SIMPLE_STATEMENT_REASON,'') = 'N' THEN '' ELSE ISNULL(ad.SIMPLE_STATEMENT_REASON,'') END AS SIMPLE_STATEMENT_REASON ,CONVERT(VARCHAR(10), CONVERT(DATE, od.REGISTER_DATE_TIME), 120) AS REGISTER_DATE_TIME ,od.CD_TYPE ,od.CD_USE_TYPE ,od.ECM_TYPE ,ad.CUSTOMS_ID_VERIFY ,ad.DROP_CODE ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'DROP_CODE' AND CODE = ad.DROP_CODE) AS DROP_REASON ,od.CLEARANCE_VIOLATION_REASON ,od.DELIVERY_NAME_CHANGED ,COUNT(od.OD_JOB_NO) OVER() AS TOTAL ,(SELECT USER_LOGIN_ID FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = od.REGISTER_USER_ID) AS REGISTER_USER_NAME ,ad.DROP_REMARKS
,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) AS CONSIGNEE_HP ,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) AS CONSIGNEE_TEL ,dbo.Cryptography(od.OD_JOB_NO, od.CUSTOMS_ID_ENC, 1) AS CUSTOMS_ID
,od.CONSIGNEE_HP ,od.CONSIGNEE_TEL ,od.CUSTOMS_ID
FROM TB_ECM_OD od LEFT OUTER JOIN TB_ECM_OD_ADDITIONAL ad ON od.OD_JOB_NO = ad.OD_JOB_NO
LEFT JOIN TB_ECM_OD_MULTI multi ON multi.OD_JOB_NO = od.OD_JOB_NO
LEFT OUTER JOIN TB_SMS_CODE_DETAIL det ON det.ENT_CODE = od.ENT_CODE AND det.GROUP_CODE = 'DROP_CODE' AND det.CODE = ad.DROP_CODE
) X
) SELECT * , ROW_NUMBER() OVER() AS NUM FROM Main_CTE
OFFSET ${startNum} ROWS FETCH NEXT ${pageSize} ROWS ONLY

/* OrderCommonCsMapper.selectInspectionDetail : 검사관리 Detail */ SELECT od.OD_JOB_NO , od.HBL_NO , od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) AS CUST_NAME_LV1 , od.CONSIGNEE_NAME_LOC AS CONSIGNEE_NAME , ad.DROP_REMARKS , od.UPDATE_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = od.UPDATE_USER_ID) AS UPDATE_USER_NAME , od.REGISTER_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = od.REGISTER_USER_ID) AS REGISTER_USER_NAME FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO WHERE 1=1
AND od.ENT_CODE = #{srchEntCode}
AND od.OD_JOB_NO = #{srchOdJobNo}

