/* OrderCommonCsMapper.insertOrderPod : 전자상거래 Order POD 저장 */
	INSERT INTO ${podTableName}(
		   POD_JOB_NO
		  ,ENT_CODE
		  ,OD_JOB_NO
		  ,POD_STATUS
		  ,POD_DATE
		  ,POD_TIME
		  ,BL_NO

		  ,DELIVERY_CODE


		  ,REMARKS

		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
	)VALUES(
		   #{podJobNo}
		  ,#{entCode}
		  ,#{odJobNo}
		  ,#{podStatus}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,CONVERT(VARCHAR(5), DATEADD(HOUR, ${gmtTime}, GETDATE()), 108)
		  ,LTRIM(RTRIM(REPLACE(#{blNo},char(9),'')))


		  ,#{remarks}


		  ,#{deliveryCode}


		  ,#{updateUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{updateUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	);

	UPDATE TB_ECM_OD_ADDITIONAL SET
	LAST_POD_STATUS = #{podStatus}
	WHERE OD_JOB_NO = #{odJobNo}

mapper.delete:
/* OrderCommonCsMapper.deleteOrderPod : Order Delete */


	DELETE FROM TB_ECM_POD
	WHERE OD_JOB_NO = #{odJobNo}
	AND POD_STATUS = #{podStatus};


	DELETE pod
	FROM TB_ECM_OD od
		 INNER JOIN TB_ECM_POD pod
		 			ON pod.OD_JOB_NO = od.OD_JOB_NO
		 			AND pod.POD_STATUS = #{podStatus}
	WHERE od.ENT_CODE = #{entCode}
	AND od.HBL_NO = LTRIM(RTRIM(#{HBL_NO}))


		AND od.MBL_NO = LTRIM(RTRIM(#{MBL_NO}));


		AND (od.MBL_NO = '' OR od.MBL_NO IS NULL);







	DELETE FROM ${podTableName}
	WHERE OD_JOB_NO = #{odJobNo}
	AND POD_STATUS = #{podStatus};


	DELETE pod
	FROM TB_ECM_OD od
		 INNER JOIN ${podTableName} pod
		 			ON pod.OD_JOB_NO = od.OD_JOB_NO
		 			AND pod.POD_STATUS = #{podStatus}
	WHERE od.ENT_CODE = #{entCode}
	AND od.HBL_NO = LTRIM(RTRIM(#{HBL_NO}))


		AND od.MBL_NO = LTRIM(RTRIM(#{MBL_NO}));


		AND (od.MBL_NO = '' OR od.MBL_NO IS NULL);

mapper.insert:
/* OrderCommonCsMapper.insertMgnMfn : 미착/무적 insert */ INSERT INTO TB_ECM_OD_ABNORMAL ( OD_JOB_NO , SEQ_NO_ID , ABNORMAL_CODE , MRN , MSN , VESSEL_FLIGHT , AR_DATE , PIECES , GWT , CNT , REGISTER_USER_ID , REGISTER_DATE_TIME , UPDATE_USER_ID , UPDATE_DATE_TIME) SELECT od.OD_JOB_NO ,(SELECT ISNULL(MAX(SEQ_NO_ID),0) + 1 FROM TB_ECM_OD_ABNORMAL WHERE OD_JOB_NO = od.OD_JOB_NO ) , #{abnormalCode} , mod.MRN , mod.MSN , mod.VESSEL_FLIGHT , mod.AR_DATE , od.PIECES , od.GWT , #{cnt} ,#{updateUserId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) ,#{updateUserId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) FROM TB_ECM_OD od INNER JOIN TB_ECM_OD mod ON od.MASTER_OD_JOB_NO = mod.OD_JOB_NO WHERE od.OD_JOB_NO = #{odJobNo};
UPDATE TB_ECM_OD_ADDITIONAL SET ABNORMAL_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE()) ,LAST_POD_STATUS = CASE WHEN ISNULL(LAST_POD_STATUS, '') < 'ECM160' THEN 'ECM160' ELSE LAST_POD_STATUS END
,UNMANAGEMENT_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE())
WHERE OD_JOB_NO = #{odJobNo}

mapper.select:
/* OrderCommonCsMapper.selectBrokerMasterSubList : broker-M House 조회 */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT A.* , COUNT(A.HBL_NO) OVER() AS SUM_COUNT ,(ISNULL(A.TARIFF, 0) + ISNULL(A.SURTAX, 0) + ISNULL(A.CLEARANCE_FEE, 0) + ISNULL(A.QURANTINE_FEE, 0) + ISNULL(A.ETC_FEE, 0)) AS TOTAL_FEE FROM ( SELECT od.OD_JOB_NO ,od.CB_CODE ,od.MRN ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = #{srchEntCode} AND CUSTOMER_CODE = od.CB_CODE AND CUSTOMER_TYPE ='BR') AS CB_NAME ,od.CUST_CODE_LV1 AS AGENT_CODE ,od.SHIPPER_CODE ,od.INSPECTION_YN ,ad.SE_INSPECTION_YN ,ad.DROP_CODE ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'DROP_CODE' AND CODE = ad.DROP_CODE) AS DROP_REASON ,ad.XRAY_YN
,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'STATUS_ORDER_CARGO' AND CODE = ad.LAST_POD_STATUS) AS LAST_POD_STATUS
,ad.LAST_POD_STATUS
,od.PO_DATE ,od.PO_NO ,od.HBL_NO ,od.MBL_NO ,od.CONSIGNEE_NAME ,od.PIECES ,od.GWT ,od.CLEARANCE_VIOLATION_CODE ,od.CLEARANCE_VIOLATION_REASON ,od.AR_DATE ,od.CLEARANCE_NOTICE_YN ,od.CLEARANCE_NOTICE_DATE ,(SELECT SUM(AP_AMOUNT) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'DTY') AS TARIFF ,(SELECT SUM(AP_AMOUNT) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'TAX') AS SURTAX ,(SELECT SUM(AP_AMOUNT) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'CFC') AS CLEARANCE_FEE ,(SELECT SUM(AP_AMOUNT) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'QUA') AS QURANTINE_FEE ,((SELECT ISNULL(SUM(AP_AMOUNT),0) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'SPTAX') +(SELECT ISNULL(SUM(AP_AMOUNT),0) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'OHTAX') +(SELECT ISNULL(SUM(AP_AMOUNT),0) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'EDTAX') )AS ETC_FEE ,od.CLEARANCE_PAYMENT_TYPE ,(SELECT CUSTOMER_NAME_ENG FROM TB_SMS_CUSTOMER WHERE ENT_CODE = #{srchEntCode} AND CUSTOMER_CODE = od.CUST_CODE_LV1 AND CUSTOMER_TYPE ='HC') AS CUST_NAME_LV1 ,(SELECT CUSTOMER_NAME_ENG FROM TB_SMS_CUSTOMER WHERE ENT_CODE = #{srchEntCode} AND CUSTOMER_CODE = od.CUST_CODE_LV2) AS CUST_NAME_LV2 ,CASE WHEN (SELECT TOP 1 REFERENCE_NO_ID FROM TB_COM_FILE_SHARE WHERE ENT_CODE = od.ENT_CODE AND FUNC_JOB_NO = od.OD_JOB_NO ) IS NULL THEN 'N' ELSE 'Y' END AS FILE_SHARE ,od.ENT_BUSINESS_CODE ,od.BOUND ,od.BOUND_TYPE ,od.CONSIGNEE_NAME_LOC ,od.CONSIGNEE_ADDRESS_LOC ,od.TARIFF_REMARKS ,ad.CB_PAYMENT_DATE_TIME ,ad.CB_SEND_DATE_TIME ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'CB_IF_STATUS' AND CODE = ad.CB_IF_STATUS) AS CB_IF_STATUS ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'CCL_TYPE' AND CODE = ad.CCL_TYPE) AS CCL_TYPE ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = od.REGISTER_USER_ID) AS REGISTER_USER_NAME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = od.UPDATE_USER_ID) AS UPDATE_USER_NAME ,od.UPDATE_DATE_TIME ,ad.CARRYIN_DATE ,ad.CARRYOUT_DATE FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
)A

mapper.sql:



AND (od.CD_TYPE IN ('N','B') OR ad.DROP_YN = 'Y')

AND od.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}


 AND od.MASTER_OD_JOB_NO IN(#{item})


 AND od.OD_JOB_NO IN(#{item})


	AND(1 = 0

	OR od.INSPECTION_YN = #{srchInspectionYn}


	OR ad.SE_INSPECTION_YN = #{srchSeInspectionYn}


	OR ad.XRAY_YN = #{srchXrayYn}


	OR ad.DROP_YN = #{srchDropYn}


	OR ad.SIMPLE_EDI_STATUS = #{srchSimpleEdiStatus}


	OR ad.SIMPLE_STATEMENT_YN = #{srchSimpleStatementYn}


	AND ISNULL((SELECT TOP 1 ABNORMAL_CODE FROM TB_ECM_OD_ABNORMAL WHERE OD_JOB_NO = od.OD_JOB_NO),'') != ''

	)


AND ad.CB_IF_STATUS = #{srchCbIfStatus}

mapper.select:
/* OrderCommonCsMapper.selectBrokerDetail : Broker Detail */ SELECT od.OD_JOB_NO , od.HBL_NO , od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) AS CUST_NAME_LV1 , od.CONSIGNEE_NAME_LOC AS CONSIGNEE_NAME , od.CLEARANCE_VIOLATION_CODE , od.CLEARANCE_VIOLATION_REASON ,(SELECT SUM(AP_AMOUNT) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'DTY') AS TARIFF ,(SELECT SUM(AP_AMOUNT) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'TAX') AS SURTAX ,(SELECT SUM(AP_AMOUNT) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'CFC') AS CLEARANCE_FEE ,(SELECT SUM(AP_AMOUNT) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'QUA') AS QURANTINE_FEE ,((SELECT ISNULL(SUM(AP_AMOUNT),0) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'SPTAX') +(SELECT ISNULL(SUM(AP_AMOUNT),0) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'OHTAX') +(SELECT ISNULL(SUM(AP_AMOUNT),0) FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = 'EDTAX') )AS ETC_FEE ,od.CLEARANCE_PAYMENT_TYPE ,CONVERT(VARCHAR(10), CONVERT(DATE, od.CLEARANCE_NOTICE_DATE), 120) AS CLEARANCE_NOTICE_DATE ,CONVERT(VARCHAR(10), CONVERT(DATE, ad.CB_PAYMENT_DATE_TIME), 120) AS CB_PAYMENT_DATE_TIME ,CONVERT(VARCHAR(10), CONVERT(DATE, ad.CLEARANCE_DATE), 120) AS CLEARANCE_DATE ,od.TARIFF_REMARKS ,fi.FILE_NAME ,fi.FILE_NAME_REMOTE ,fi.REFERENCE_NO_ID ,fi.FILE_SIZE ,fi.FILE_EXT FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN ( SELECT TOP 1 FUNC_JOB_NO , FILE_NAME , FILE_NAME_REMOTE , REFERENCE_NO_ID , FILE_SIZE , FILE_EXT FROM TB_COM_FILE_SHARE WHERE FUNC_JOB_NO = #{srchOdJobNo} ORDER BY REGISTER_DATE_TIME DESC ) fi ON fi.FUNC_JOB_NO = od.OD_JOB_NO WHERE 1=1
AND od.ENT_CODE = #{srchEntCode}
AND od.OD_JOB_NO = #{srchOdJobNo}
AND od.HBL_NO = #{srchNo}

mapper.update:
/* OrderCommonCsMapper.saveBrokerUpdate : Broker 수정 */
UPDATE TB_ECM_OD SET
UPDATE_USER_ID = #{registerUserId}
,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
,CLEARANCE_VIOLATION_CODE = #{clearanceViolationCode}
,CLEARANCE_VIOLATION_REASON = #{clearanceViolationReason}
,CLEARANCE_PAYMENT_TYPE = #{clearancePaymentType}
,CLEARANCE_NOTICE_DATE = #{clearanceNoticeDate}
,TARIFF_REMARKS = #{tariffRemarks}
WHERE OD_JOB_NO = #{odJobNo}

UPDATE TB_ECM_OD_ADDITIONAL SET
OD_JOB_NO = OD_JOB_NO
,CB_PAYMENT_DATE_TIME = #{cbPaymentDateTime}
,CLEARANCE_DATE = #{clearanceDate}
WHERE OD_JOB_NO = #{odJobNo}

mapper.select:
/* OrderCommonCsMapper.selectSubMultiWgList : 이영(중량) 화물관리 List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT multi.OD_JOB_NO ,multi.SEQ_NO_ID ,CASE WHEN od.BOUND = 'AIR' THEN '항공수입' ELSE '해상수입' END AS BOUND ,multi.RETURN_DELIVERY_STATUS as LAST_POD_STATUS ,od.BOUND_TYPE ,od.PO_DATE ,od.OB_DATE ,od.PIECES ,od.MULTI_YN ,(SELECT TOP 1 POD_M.POD_DATE from TB_ECM_POD_04_M POD_M WHERE POD_M.OD_JOB_NO = od.OD_JOB_NO AND POD_M.BL_NO = COALESCE(NULLIF(multi.DELIVERY_NO_CHANGED, ''), multi.DELIVERY_NO) AND POD_M.POD_STATUS = 'ECM340' ) AS POD_DATE_CHK ,od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) as CUST_NAME_LV1 ,od.CUST_CODE_LV2 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) as CUST_NAME_LV2 ,od.AR_DATE ,od.HBL_NO ,od.CONSIGNEE_NAME_LOC AS CONSIGNEE_NAME ,od.PIECES AS HOUSE_PIECES ,od.GWT ,od.VWT AS HOUSE_VWT ,od.AMOUNT_CUR ,multi.DELIVERY_CODE ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE' AND CODE = od.DELIVERY_CODE) AS DELIVERY_NAME_OD ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE' AND CODE = multi.DELIVERY_CODE) AS DELIVERY_NAME_MULTI ,multi.DELIVERY_NO ,multi.DELIVERY_NO_CHANGED ,multi.CUSTOMER_CODE ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = multi.CUSTOMER_CODE) AS CUSTOMER_NAME ,multi.PAYMENT_GUBN ,ISNULL((SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_PAYMENT_GUBN' AND CODE = multi.PAYMENT_GUBN), '') AS PAYMENT_GUBN_NAME ,multi.DELIVERY_FEE ,multi.DELIVERY_SPECIAL_FEE ,multi.DELIVERY_INSURANCE_FEE ,ISNULL(multi.DELIVERY_FEE, 0) + ISNULL(multi.DELIVERY_SPECIAL_FEE, 0) + ISNULL(multi.DELIVERY_INSURANCE_FEE, 0) AS TOTAL_FEE ,multi.DIM_WIDTH ,multi.DIM_LENGTH ,multi.DIM_HEIGHT ,multi.VWT AS MULTI_VWT ,multi.PIECES AS MULTI_PIECES ,multi.REMARKS ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = multi.INPUT_USER_ID) AS INPUT_USER_NAME ,multi.INPUT_METHOD ,multi.INPUT_DATE_TIME ,multi.UPDATE_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = multi.UPDATE_USER_ID) AS UPDATE_USER_NAME ,multi.REGISTER_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = multi.REGISTER_USER_ID) AS REGISTER_USER_NAME ,ad.SMS_INFORM_YN ,CONVERT(VARCHAR(16), DATEADD(hh, -9, ad.SMS_INFORM_DATE), 120) AS SMS_INFORM_DATE ,ad.SMS_INFORM_RES_YN ,CONVERT(VARCHAR(16), DATEADD(hh, -9, ad.SMS_INFORM_RES_DATE), 120) AS SMS_INFORM_RES_DATE
,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) AS CONSIGNEE_HP
,od.CONSIGNEE_HP
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_MULTI multi ON od.OD_JOB_NO = multi.OD_JOB_NO LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON od.OD_JOB_NO = ad.OD_JOB_NO WHERE 1=1 AND NOT EXISTS ( SELECT 1 FROM TB_ECM_OD_DLV_CHANGE_INFO DCI WHERE DCI.SEQ_NO_ID = multi.SEQ_NO_ID AND DCI.OD_JOB_NO = multi.OD_JOB_NO -- AND DCI.DELIVERY_NO_CHANGED IS NOT NULL -- AND DCI.DELIVERY_NO_CHANGED != '' ) AND NOT EXISTS ( SELECT 1 FROM TB_ECM_OD_RESEND_INFO RE WHERE RE.SEQ_NO_ID = multi.SEQ_NO_ID AND RE.OD_JOB_NO = multi.OD_JOB_NO )
AND od.BOUND = #{srchBound}
AND od.BOUND_TYPE = #{srchBoundType}
AND ${srchCusType} = #{srchCustomerCode}
AND multi.PAYMENT_GUBN = #{srchDeliveryPaymentType}
AND ISNULL(multi.DELIVERY_CODE, '') = '' AND multi.DELIVERY_CODE = #{srchDeliveryCode}
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND od.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}
AND ISNULL(multi.DELIVERY_CODE, '') != '' AND ISNULL(multi.RETURN_DELIVERY_STATUS, '') < 'ECM340'
AND multi.RETURN_DELIVERY_STATUS = #{srchStatus}
AND od.OD_JOB_NO = #{odJobNo} AND multi.SEQ_NO_ID = #{seqNoId}
AND ad.SMS_INFORM_YN = 'Y' AND (ad.SMS_INFORM_RES_YN IS NULL OR ad.SMS_INFORM_RES_YN = 'N')
AND (ad.SMS_INFORM_YN IS NULL OR ad.SMS_INFORM_YN = '' OR ad.SMS_INFORM_YN = 'N')
AND (ad.SMS_INFORM_YN = 'Y' AND ad.SMS_INFORM_RES_YN = 'Y')
AND (ad.SMS_INFORM_YN = 'Y' AND ad.SMS_INFORM_RES_YN = 'N')

mapper.delete:
/* OrderCommonCsMapper.deleteMultiWgOrder : 이영(중량) Delete */
DELETE FROM TB_ECM_OD_MULTI
WHERE OD_JOB_NO = #{odJobNo}
AND SEQ_NO_ID =#{seqNoId}

mapper.insert:
/* OrderCommonCsMapper.insertMulti : Order 멀티(중량)화물 insert */
INSERT INTO TB_ECM_OD_MULTI(
	OD_JOB_NO
	,SEQ_NO_ID
	,DELIVERY_NO
	,DELIVERY_CODE
	,CUSTOMER_CODE
	,DELIVERY_NO_CHANGED
	,PAYMENT_GUBN
	,DELIVERY_FEE
	,DELIVERY_SPECIAL_FEE
