/* OrderCommonCsMapper.selectBondedTransList : 보세운송 관리 List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.OD_JOB_NO ,od.BOUND ,od.BOUND_TYPE ,odAdd.LAST_POD_STATUS ,od.PO_DATE ,od.OB_DATE ,od.AR_DATE ,od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) as CUST_NAME_LV1 ,od.CUST_CODE_LV2 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) as CUST_NAME_LV2 ,od.MBL_NO ,od.HBL_NO ,od.CONSIGNEE_NAME_LOC AS CONSIGNEE_NAME ,od.PIECES ,bond.BONDED_TRANS_DATE ,bond.BONDED_TRANS_TYPE ,bond.INSPECTION_DROP ,bond.TRANSPORT_DATE ,bond.CARRYOUT_DATE ,bond.CARRYOUT_REMARK ,bond.INPUT_METHOD ,bond.UPDATE_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = bond.UPDATE_USER_ID) AS UPDATE_USER_NAME ,bond.REGISTER_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = bond.REGISTER_USER_ID) AS REGISTER_USER_NAME FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO INNER JOIN TB_ECM_OD_BONDED_TRANS bond ON od.OD_JOB_NO = bond.OD_JOB_NO WHERE 1=1
AND od.BOUND = #{srchBound}
AND od.BOUND_TYPE = #{srchBoundType}
AND ${srchCusType} = #{srchCustomerCode}
AND ${srchBondedTransType} LIKE CONCAT('%',#{srchBondedTrans},'%')
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND od.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}
AND od.OD_JOB_NO = #{odJobNo}

mapper.update:
