	  ,CARRYOUT_REMARK = #{carryoutRemark}
	  ,INPUT_METHOD = CASE WHEN INPUT_METHOD IS NULL THEN #{inputMethod} ELSE INPUT_METHOD END
	  ,REGISTER_DATE_TIME =CASE WHEN REGISTER_DATE_TIME IS NULL THEN DATEADD(HOUR, ${gmtTime}, GETDATE()) ELSE REGISTER_DATE_TIME END
