/* OrderCommonCsMapper.selectChangeDeliveryList : 송장호출(주소변경) 관리 List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.OD_JOB_NO ,od.BOUND ,od.PIECES ,od.MULTI_YN ,od.BOUND_TYPE ,(SELECT TOP 1 POD_M.POD_DATE FROM TB_ECM_POD_04_M POD_M WHERE POD_M.OD_JOB_NO = od.OD_JOB_NO AND POD_M.BL_NO = COALESCE(NULLIF(multi.DELIVERY_NO_CHANGED, ''), multi.DELIVERY_NO) AND POD_M.POD_STATUS = 'ECM340' ) AS POD_DATE_CHK ,ad.LAST_POD_STATUS ,od.PO_DATE ,od.OB_DATE ,od.AR_DATE ,od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) as CUST_NAME_LV1 ,od.CUST_CODE_LV2 ,od.CUST_CODE_LV3 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) as CUST_NAME_LV2 ,CASE WHEN multi.OD_JOB_NO IS NULL THEN od.HBL_NO ELSE multi.DELIVERY_NO END AS HBL_NO ,dlv.SEQ_NO_ID ,dlv.DELIVERY_NAME_CHANGED ,dlv.DELIVERY_ZIPCODE_CHANGED ,dlv.DELIVERY_ADDRESS_CHANGED ,dlv.DELIVERY_TEL_CHANGED ,dlv.DELIVERY_CODE_CHANGED ,(SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE' AND CODE = dlv.DELIVERY_CODE_CHANGED) AS DELIVERY_NAME ,dlv.DELIVERY_NO_CHANGED ,dlv.INPUT_METHOD ,dlv.DELIVERY_CHANGED_DATE ,dlv.UPDATE_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = dlv.UPDATE_USER_ID) AS UPDATE_USER_NAME ,dlv.REGISTER_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = dlv.REGISTER_USER_ID) AS REGISTER_USER_NAME , CASE WHEN od.CUST_CODE_LV3 IS NOT NULL THEN 3 WHEN od.CUST_CODE_LV2 IS NOT NULL THEN 2 ELSE 1 END AS STOCK_CUST_LV ,ad.PRINT_DATE ,dlv.CONFIRM_YN ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = dlv.CONFIRM_USER_ID) AS CONFIRM_USER_NAME ,ad.SMS_INFORM_YN ,CONVERT(VARCHAR(16), DATEADD(hh, -9, ad.SMS_INFORM_DATE), 120) AS SMS_INFORM_DATE ,ad.SMS_INFORM_RES_YN ,CONVERT(VARCHAR(16), DATEADD(hh, -9, ad.SMS_INFORM_RES_DATE), 120) AS SMS_INFORM_RES_DATE FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_DLV_CHANGE_INFO dlv ON od.OD_JOB_NO = dlv.OD_JOB_NO LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON od.OD_JOB_NO = ad.OD_JOB_NO LEFT JOIN TB_ECM_OD_MULTI multi ON od.OD_JOB_NO = multi.OD_JOB_NO AND ((multi.SEQ_NO_ID IS NOT NULL AND dlv.SEQ_NO_ID = multi.SEQ_NO_ID) OR multi.SEQ_NO_ID = '0') WHERE 1=1
AND od.BOUND = #{srchBound}
AND od.BOUND_TYPE = #{srchBoundType}
AND ${srchCusType} = #{srchCustomerCode}
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND od.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}
AND od.OD_JOB_NO = #{odJobNo}
AND ad.SMS_INFORM_YN = 'Y' AND (ad.SMS_INFORM_RES_YN IS NULL OR ad.SMS_INFORM_RES_YN = 'N')
AND (ad.SMS_INFORM_YN IS NULL OR ad.SMS_INFORM_YN = '' OR ad.SMS_INFORM_YN = 'N')
AND (ad.SMS_INFORM_YN = 'Y' AND ad.SMS_INFORM_RES_YN = 'Y')
AND (ad.SMS_INFORM_YN = 'Y' AND ad.SMS_INFORM_RES_YN = 'N')

/* OrderCommonCsMapper.selectChangeDeliveryDetail : 송장호출(주소변경) 상세조회 */ SELECT od.OD_JOB_NO ,CASE WHEN multi.OD_JOB_NO IS NULL THEN od.HBL_NO ELSE multi.DELIVERY_NO END AS HBL_NO ,od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) as CUST_NAME_LV1 ,od.CUST_CODE_LV2 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) as CUST_NAME_LV2 ,dlv.SEQ_NO_ID ,dlv.DELIVERY_NAME_CHANGED ,dlv.DELIVERY_ZIPCODE_CHANGED ,dlv.DELIVERY_ADDRESS_CHANGED ,dlv.DELIVERY_TEL_CHANGED ,dlv.DELIVERY_CODE_CHANGED ,dlv.DELIVERY_NO_CHANGED ,dlv.INPUT_METHOD ,dlv.DELIVERY_CHANGED_DATE ,dlv.REGISTER_USER_ID ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = dlv.REGISTER_USER_ID) AS REGISTER_USER_NAME ,dlv.REGISTER_DATE_TIME ,dlv.UPDATE_USER_ID ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = dlv.UPDATE_USER_ID) AS UPDATE_USER_NAME ,dlv.UPDATE_DATE_TIME FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_DLV_CHANGE_INFO dlv ON od.OD_JOB_NO = dlv.OD_JOB_NO LEFT JOIN TB_ECM_OD_MULTI multi ON od.OD_JOB_NO = multi.OD_JOB_NO AND ((multi.SEQ_NO_ID IS NOT NULL AND dlv.SEQ_NO_ID = multi.SEQ_NO_ID) OR multi.SEQ_NO_ID = '0') WHERE 1=1 AND od.ENT_CODE = #{entCode} AND od.OD_JOB_NO = #{odJobNo}
AND dlv.SEQ_NO_ID IS NULL
AND dlv.SEQ_NO_ID = #{seqNoId}

