mapper.select:
/* OrderCommonCsMapper.selectMultiOdJobNoByBlNo : B/L번호로 오더관리번호조회(multi건) */
SELECT CASE WHEN od.OD_JOB_NO IS NOT NULL THEN od.OD_JOB_NO
            ELSE MULTI_OD.OD_JOB_NO
       END AS OD_JOB_NO
       , MULTI_OD.SEQ_NO_ID
FROM (SELECT #{hblNo} AS HBL_NO) A
LEFT JOIN TB_ECM_OD od
    ON od.ENT_CODE = #{entCode}
    AND od.HBL_NO = A.HBL_NO

    AND od.BOUND = #{bound}


    AND od.BOUND_TYPE = #{boundType}

LEFT JOIN (
    SELECT ecmOd.OD_JOB_NO, multi.DELIVERY_NO, multi.SEQ_NO_ID
    FROM TB_ECM_OD_MULTI multi
    INNER JOIN TB_ECM_OD ecmOd ON ecmOd.OD_JOB_NO = multi.OD_JOB_NO
        AND ecmOd.ENT_CODE = #{entCode}

        AND ecmOd.BOUND = #{bound}


        AND ecmOd.BOUND_TYPE = #{boundType}

) MULTI_OD ON MULTI_OD.DELIVERY_NO = A.HBL_NO

/* OrderCommonCsMapper.selectQuickRequestList :퀵요청 관리 List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.OD_JOB_NO ,od.BOUND ,od.BOUND_TYPE ,od.PO_DATE ,od.OB_DATE ,od.AR_DATE ,od.CONSIGNEE_NAME_LOC AS CONSIGNEE_NAME ,od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) as CUST_NAME_LV1 ,od.CUST_CODE_LV2 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) as CUST_NAME_LV2 ,CASE WHEN multi.OD_JOB_NO IS NULL THEN od.HBL_NO ELSE multi.DELIVERY_NO END AS HBL_NO ,CASE WHEN multi.OD_JOB_NO IS NULL THEN od.PIECES ELSE multi.PIECES END AS PIECES ,quick.SEQ_NO_ID ,quick.INCOTERMS ,quick.QUICK_FEE ,ISNULL((SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_PAYMENT_GUBN' AND CODE = quick.INCOTERMS), '') AS INCOTERMS_NAME ,quick.REMARK ,quick.TAKE_OVER_DATE ,quick.DRIVER_NAME ,quick.INPUT_METHOD ,quick.UPDATE_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = quick.UPDATE_USER_ID) AS UPDATE_USER_NAME ,quick.REGISTER_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = quick.REGISTER_USER_ID) AS REGISTER_USER_NAME FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_QUICK_INFO quick ON od.OD_JOB_NO = quick.OD_JOB_NO LEFT JOIN TB_ECM_OD_MULTI multi ON od.OD_JOB_NO = multi.OD_JOB_NO AND ((multi.SEQ_NO_ID IS NOT NULL AND quick.SEQ_NO_ID = multi.SEQ_NO_ID) OR multi.SEQ_NO_ID = '0') WHERE 1=1
AND od.BOUND = #{srchBound}
AND od.BOUND_TYPE = #{srchBoundType}
AND ${srchCusType} = #{srchCustomerCode}
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND od.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}
AND od.OD_JOB_NO = #{odJobNo}

/* OrderCommonCsMapper.selectQuickRequestDetail : 퀵 상세조회 */ SELECT od.OD_JOB_NO ,CASE WHEN multi.OD_JOB_NO IS NULL THEN od.HBL_NO ELSE multi.DELIVERY_NO END AS HBL_NO ,od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) as CUST_NAME_LV1 ,od.CUST_CODE_LV2 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) as CUST_NAME_LV2 ,od.CONSIGNEE_NAME_LOC AS CONSIGENEE_NAME ,CASE WHEN multi.OD_JOB_NO IS NULL THEN od.PIECES ELSE multi.PIECES END AS PIECES ,quick.SEQ_NO_ID ,quick.INCOTERMS ,quick.QUICK_FEE ,ISNULL((SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_PAYMENT_GUBN' AND CODE = quick.INCOTERMS), '') AS INCOTERMS_NAME ,quick.REMARK ,quick.TAKE_OVER_DATE ,quick.DRIVER_NAME ,quick.REGISTER_USER_ID ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = quick.REGISTER_USER_ID) AS REGISTER_USER_NAME ,quick.INPUT_METHOD ,quick.REGISTER_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = quick.UPDATE_USER_ID) AS UPDATE_USER_NAME ,quick.UPDATE_USER_ID ,quick.UPDATE_DATE_TIME FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_QUICK_INFO quick ON od.OD_JOB_NO = quick.OD_JOB_NO LEFT JOIN TB_ECM_OD_MULTI multi ON od.OD_JOB_NO = multi.OD_JOB_NO AND ((multi.SEQ_NO_ID IS NOT NULL AND quick.SEQ_NO_ID = multi.SEQ_NO_ID) OR multi.SEQ_NO_ID = '0') WHERE 1=1 AND od.ENT_CODE = #{entCode} AND od.OD_JOB_NO = #{odJobNo}
AND quick.SEQ_NO_ID IS NULL
AND quick.SEQ_NO_ID = #{seqNoId}

