/* OrderCommonCsMapper.selectReturnMngList :반품관리 List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.OD_JOB_NO ,mt.SEQ_NO_ID ,CASE WHEN od.BOUND = 'AIR' THEN '항공수입' ELSE '해상수입' END AS BOUND ,od.BOUND_TYPE ,od.PO_DATE ,od.OB_DATE ,od.AR_DATE ,od.CONSIGNEE_NAME_LOC AS CONSIGNEE_NAME ,od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) as CUST_NAME_LV1 ,od.CUST_CODE_LV2 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) as CUST_NAME_LV2 ,od.PO_NO ,CASE WHEN mt.OD_JOB_NO IS NOT NULL THEN mt.DELIVERY_NO ELSE od.HBL_NO END AS HBL_NO ,CASE WHEN mt.OD_JOB_NO IS NOT NULL THEN mt.PIECES ELSE od.PIECES END AS PIECES ,od.AMOUNT_CUR as TOTAL_FEE ,od.COMMODITY_ITEM AS ITEM_NAME ,rsn.INPUT_METHOD ,CASE WHEN mt.OD_JOB_NO IS NOT NULL THEN mt.RETURN_REQUEST_ID ELSE ad.RETURN_REQUEST_ID END AS RETURN_REQUEST_ID ,CASE WHEN mt.OD_JOB_NO IS NOT NULL THEN mt.RETURN_DELIVERY_CODE ELSE ad.RETURN_DELIVERY_CODE END AS RETURN_DELIVERY_CODE ,(SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE' AND CODE = ad.RETURN_DELIVERY_CODE) AS RETURN_DELIVERY_NAME ,CASE WHEN mt.OD_JOB_NO IS NOT NULL THEN mt.RETURN_DELIVERY_NO ELSE od.RETURN_DELIVERY_NO END AS RETURN_DELIVERY_NO ,CASE WHEN ISNULL(CASE WHEN mt.OD_JOB_NO IS NOT NULL THEN mt.RETURN_DLV_REQ_DATE ELSE ad.RETURN_DLV_REQ_DATE END, '') = '' THEN 'N' ELSE 'Y' END AS SEND_CHK ,CASE WHEN mt.OD_JOB_NO IS NOT NULL THEN mt.RETURN_REQ_DATE ELSE ad.RETURN_REQ_DATE END AS RETURN_REQ_DATE ,CASE WHEN mt.OD_JOB_NO IS NOT NULL THEN mt.RETURN_REG_DATE ELSE ad.RETURN_REG_DATE END AS RETURN_REG_DATE ,CASE WHEN mt.RETURN_DELIVERY_STATUS IN ('ECM504', 'ECM506', 'ECM510', 'ECM520', 'ECM530', 'ECM540', 'ECM550', 'ECM551') THEN mt.RETURN_DELIVERY_STATUS ELSE NULL END AS RETURN_DELIVERY_STATUS ,CASE WHEN mt.RETURN_DELIVERY_STATUS IN ('ECM504', 'ECM506', 'ECM510', 'ECM520', 'ECM530', 'ECM540', 'ECM550', 'ECM551') THEN (SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = mt.RETURN_DELIVERY_STATUS AND GROUP_CODE = 'STATUS_ORDER_CARGO') ELSE NULL END AS RETURN_DELVIERY_STATUS_NAME ,od.CONSIGNEE_NAME_LOC AS RETURN_CUSTOMER ,od.CONSIGNEE_ADDRESS_LOC AS RETURN_ADDRESS ,od.CONSIGNEE_ZIPCODE AS RETURN_ZIPCODE ,CASE WHEN ISNULL(od.CONSIGNEE_HP,'') = '' THEN dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) ELSE ISNULL(od.CONSIGNEE_HP,'') END AS RETURN_TEL ,ent.ENT_NAME AS CARRYIN ,delivery.SENDER_ADDR + ' ' + delivery.SENDER_ADDR_DTL AS CARRYIN_ADDRESS ,delivery.SENDER_ZIPCODE AS CARRYIN_ZIPCODE ,delivery.SENDER_TELNO1 + delivery.SENDER_TELNO2 + delivery.SENDER_TELNO3 AS CARRYIN_TEL ,rsn.CARRYIN_DATE_TIME ,rsn.CARRYIN_USER_ID ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = rsn.CARRYIN_USER_ID) AS CARRYIN_USER_NAME ,rsn.CARRYIN_WH_LOCATION ,CASE WHEN rsn.RETURN_PROCESS_TYPE = '01' THEN '폐기' WHEN rsn.RETURN_PROCESS_TYPE = '02' THEN '재발송' WHEN rsn.RETURN_PROCESS_TYPE = '03' THEN '반송(수출)' END AS RETURN_PROCESS_TYPE ,rsn.CARRYOUT_DATE_TIME ,rsn.CARRYOUT_USER_ID ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = rsn.CARRYOUT_USER_ID) AS CARRYOUT_USER_NAME ,rsn.RESEND_DELIVERY_CODE ,(SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE' AND CODE = rsn.RESEND_DELIVERY_CODE) AS RESEND_DELIVERY_NAME ,rsn.RESEND_DATE_TIME ,rsn.RESEND_DELIVERY_NO ,rsn.RESEND_INCOTERMS ,ISNULL((SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_PAYMENT_GUBN' AND CODE = rsn.RESEND_INCOTERMS), '') AS RESEND_INCOTERMS_NAME ,rsn.RESEND_FEE ,rsn.RESEND_ADDRESS ,rsn.RESEND_ZIPCODE ,rsn.RESEND_TEL ,rsn.RESEND_STATUS ,rsn.RESEND_REMARK ,rsn.UPDATE_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = rsn.UPDATE_USER_ID) AS UPDATE_USER_NAME ,rsn.REGISTER_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = rsn.REGISTER_USER_ID) AS REGISTER_USER_NAME FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_MULTI mt ON mt.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_SMS_DELIVERY_COMP_INFO delivery ON od.ENT_CODE = delivery.ENT_CODE AND od.BOUND = delivery.BOUND AND od.CUST_CODE_LV1 = delivery.CUSTOMER_CODE LEFT JOIN exps_master.dbo.TB_SMS_ENTERPRISE ent ON od.ENT_CODE = ent.ENT_CODE INNER JOIN TB_ECM_OD_RESEND_INFO rsn ON od.OD_JOB_NO = rsn.OD_JOB_NO AND mt.SEQ_NO_ID = rsn.SEQ_NO_ID WHERE 1=1 AND od.BL_TYPE_MH = 'H'
AND od.BOUND = #{srchBound}
AND od.BOUND_TYPE = #{srchBoundType}
AND rsn.RETURN_PROCESS_TYPE = #{srchReturn}
AND mt.RETURN_DELIVERY_STATUS = #{srchStatus}
AND ((mt.RETURN_DELIVERY_STATUS IS NULL) OR (mt.RETURN_DELIVERY_STATUS < 'ECM504'))
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND od.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}
AND od.OD_JOB_NO = #{odJobNo}
AND (rsn.RETURN_PROCESS_TYPE IS NULL AND rsn.CARRYIN_DATE_TIME IS NULL AND rsn.CARRYOUT_DATE_TIME IS NULL)
AND (rsn.RETURN_PROCESS_TYPE IS NOT NULL OR rsn.CARRYIN_DATE_TIME IS NOT NULL OR rsn.CARRYOUT_DATE_TIME IS NOT NULL)

mapper.update:
