UPDATE TB_ECM_OD_RESEND_INFO SET
UPDATE_USER_ID = #{registerUserId}
,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())



		,RETURN_PROCESS_TYPE = '01'


		,CARRYIN_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
		,CARRYIN_USER_ID = #{registerUserId}			

		,CARRYIN_WH_LOCATION = #{carryinWhLocation}



		,RETURN_PROCESS_TYPE = '02'


		,RETURN_PROCESS_TYPE = '03'


		,CARRYOUT_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
		,CARRYOUT_USER_ID = #{registerUserId}	


		,RESEND_DELIVERY_CODE = #{resendDeliveryCode}



WHERE 	(OD_JOB_NO = #{item.odJobNo} AND SEQ_NO_ID = #{item.seqNoId})

