/* OrderCommonCsMapper.selectUnusualMngList : 이례화물관리 List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.OD_JOB_NO ,od.BOUND_TYPE ,CASE WHEN (SELECT TOP 1 REFERENCE_NO_ID FROM TB_COM_FILE_SHARE WHERE ENT_CODE = od.ENT_CODE AND FUNC_JOB_NO = od.OD_JOB_NO ) IS NULL THEN 'N' ELSE 'Y' END AS FILE_SHARE ,ad.LAST_POD_STATUS ,od.PO_DATE ,od.OB_DATE ,od.AR_DATE ,od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) as CUST_NAME_LV1 ,od.CUST_CODE_LV2 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) as CUST_NAME_LV2 ,od.CD_TYPE ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND CODE = od.CD_TYPE AND GROUP_CODE = 'CD_TYPE') AS CD_TYPE_NAME ,od.PO_NO ,od.MBL_NO ,od.HBL_NO ,od.CB_CODE ,od.CB_NAME ,od.REMARKS ,ad.DROP_CODE ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'DROP_CODE' AND CODE = ad.DROP_CODE) AS DROP_REASON ,CASE WHEN pod.POD_STATUS = 'ECM160' THEN odAdnor.ABNORMAL_CODE ELSE ad.UNUSUAL_CODE END AS UNUSUAL_CODE ,CASE WHEN pod.POD_STATUS = 'ECM160' THEN (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ABNORMALITY_CODE' AND CODE = odAdnor.ABNORMAL_CODE) ELSE (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'UNUSUAL_CODE' AND CODE = ad.UNUSUAL_CODE) END AS UNUSUAL_CODE_NAME ,ad.UNUSUAL_DATE_TIME ,ad.UNUSUAL_REASON FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_POD_02 pod ON od.OD_JOB_NO = pod.OD_JOB_NO AND pod.POD_STATUS = 'ECM160' LEFT JOIN TB_ECM_OD_ABNORMAL odAdnor ON od.OD_JOB_NO = odAdnor.OD_JOB_NO WHERE 1=1 AND od.BL_TYPE_MH = 'H' AND ( ad.UNUSUAL_CODE IS NOT NULL OR pod.OD_JOB_NO IS NOT NULL )
AND od.BOUND = #{srchBound}
AND od.BOUND_TYPE = #{srchBoundType}
AND pod.OD_JOB_NO IS NOT NULL
AND ad.UNUSUAL_CODE = #{srchUnusual}
AND ${srchCusType} = #{srchCustomerCode}
AND ${srchNoType} IN (#{item})
AND ${srchNoType} = #{srchNo}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND od.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}
AND od.OD_JOB_NO = #{odJobNo}

