mapper.insert:
/** OrderCommonCsMapper.createHbl */ INSERT INTO TB_ECM_OD( OD_JOB_NO ,ENT_CODE ,ENT_BUSINESS_CODE ,SOLUTION ,BOUND ,BOUND_TYPE ,PO_DATE ,BL_TYPE_MH ,BL_TYPE_IERT ,CONSOL_YN ,HBL_NO ,CUST_CODE_LV1 ,DELIVERY_FEE ,CD_TYPE ,CD_TYPE_OLD ,CD_USE_TYPE ,ECM_TYPE ,ECM_BUY_TYPE ,CUSTOMS_ID_TYPE ,INSPECTION_YN ,GE_INSPECTION_YN ,MULTI_YN ,FTA_YN ,UNIT_PIECES ,PIECES ,PIECES_REAL ,GWT ,GWT_LBS ,CBM ,AMOUNT_LOC ,AMOUNT_CUR ,AMOUNT_USD ,FINISH_YN ,DIM_WIDTH ,DIM_HEIGHT ,DIM_LENGTH ,DOCUMENT_YN ,REGISTER_USER_ID ,REGISTER_DATE_TIME ,UPDATE_USER_ID ,UPDATE_DATE_TIME )VALUES( #{odJobNo} ,#{entCode} ,#{entBusinessCode} ,'ECM' ,#{bound} ,#{boundType} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) ,'H' ,'I' ,'N' ,LTRIM(RTRIM(REPLACE(#{hblNo},char(9),''))) ,#{custCodeLv1} ,0 ,'N' ,'N' ,'1' ,'A' ,'A' ,'A' ,'N' ,'N' ,'N' ,'Y' ,'PCS' ,0 ,0 ,0 ,0 ,0 ,0 ,0 ,0 ,'N' ,0 ,0 ,0 ,'N' ,#{registerUserId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) ,#{registerUserId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) );
INSERT TB_ECM_OD_ADDITIONAL( OD_JOB_NO ,CUSTOMS_ID_VERIFY ,CUSTOMS_ID_ERROR ,LAST_POD_STATUS ,HBL_NO ,CD_TYPE ,BL_TYPE_MH )VALUES( #{odJobNo} ,'X' ,'개인통관코드 입력 값이 없습니다.' ,'ECM010' ,LTRIM(RTRIM(REPLACE(#{hblNo},char(9),''))) ,'N' ,'H' );
INSERT INTO TB_ECM_POD_01( POD_JOB_NO ,ENT_CODE ,OD_JOB_NO ,POD_STATUS ,POD_DATE ,POD_TIME ,BL_NO ,REGISTER_USER_ID ,REGISTER_DATE_TIME ,UPDATE_USER_ID ,UPDATE_DATE_TIME )VALUES( #{podJobNo} ,#{entCode} ,#{odJobNo} ,'ECM010' ,DATEADD(HOUR, ${gmtTime}, GETDATE()) ,CONVERT(VARCHAR(5), DATEADD(HOUR, ${gmtTime}, GETDATE()), 108) ,LTRIM(RTRIM(REPLACE(#{hblNo},char(9),''))) ,#{registerUserId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) ,#{registerUserId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) );

/** OrderCommonCsMapper.insertMultiDelivery */
INSERT INTO TB_ECM_OD_MULTI(
	OD_JOB_NO
	,SEQ_NO_ID
	,DELIVERY_NO
	,DELIVERY_CODE
	,PIECES

	,DELIVERY_NO_CHANGED

	,UPDATE_USER_ID
	,UPDATE_DATE_TIME
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
)VALUES(
	#{odJobNo}
	,#{seqNoId}
	,#{hblNo}
	,#{deliveryCode}
	,1

	,#{stockMutliNo}

	,#{updateUserId}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())
	,#{updateUserId}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())
)

UPDATE TB_ECM_OD SET
	MULTI_YN = 'Y'
WHERE OD_JOB_NO = #{odJobNo}

mapper.update:
		/** OrderCommonCsMapper.insertResendRequest */
		UPDATE TB_ECM_OD_RESEND_INFO SET
			UPDATE_USER_ID = #{registerUserId}
			,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
			,RESEND_DELIVERY_CODE = #{resendDeliveryCode}
		WHERE OD_JOB_NO = #{odJobNo}
		AND SEQ_NO_ID = #{odJobNoSeqNoId}

		IF @@ROWCOUNT = 0

		INSERT INTO TB_ECM_OD_RESEND_INFO(
			   OD_JOB_NO
			  ,SEQ_NO_ID
			  ,INPUT_METHOD
			  ,RESEND_DELIVERY_NO
			  ,RESEND_DELIVERY_CODE
			  ,REGISTER_USER_ID
			  ,REGISTER_DATE_TIME
			  ,UPDATE_USER_ID
			  ,UPDATE_DATE_TIME
		)VALUES(
			   #{odJobNo}
			  ,#{odJobNoSeqNoId}
			  ,#{inputMethod}
			  ,#{resendDeliveryCode}
			  ,#{registerUserId}


                      ,#{requestDate}


                      ,DATEADD(HOUR, ${gmtTime}, GETDATE())


			  ,#{registerUserId}
			  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		)

		/** OrderCommonCsMapper.updateMultiDelivery */
		UPDATE TB_ECM_OD_MULTI
		SET 
			UPDATE_USER_ID = #{updateUserId}
			,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
			,RETURN_REQ_DATE = CONVERT(DATE, #{returnReqDate}, 23)
			,RETURN_REQUEST_ID = #{returnRequestId}
			,RETURN_DELIVERY_CODE = #{returnDeliveryCode}
			,RETURN_DELIVERY_NO = #{returnDeliveryNo}
			,RETURN_REG_DATE = CONVERT(DATE, #{returnRegDate}, 23)
		WHERE OD_JOB_NO = #{odJobNo}
		AND ISNULL(SEQ_NO_ID, 0) = #{odJobNoSeqNoId}
		;

    	IF @@ROWCOUNT = 0

    	INSERT INTO TB_ECM_OD_MULTI(
			OD_JOB_NO
			,SEQ_NO_ID
			,DELIVERY_NO
			,PIECES
			,RETURN_REQ_DATE
			,RETURN_REQUEST_ID
			,RETURN_DELIVERY_CODE
			,RETURN_DELIVERY_NO
			,RETURN_REG_DATE
			,REGISTER_USER_ID
			,REGISTER_DATE_TIME
		)VALUES(
			#{odJobNo}
			,#{odJobNoSeqNoId}
			,#{hblNo}
			,1
			,CONVERT(DATE, #{returnReqDate}, 23)
			,#{returnRequestId}
			,#{returnDeliveryCode}
			,#{returnDeliveryNo}
			,CONVERT(DATE, #{returnRegDate}, 23)
			,#{updateUserId}
			,DATEADD(HOUR, ${gmtTime}, GETDATE())
		);

/** OrderCommonCsMapper.updateDeliveryStatus */
UPDATE TB_ECM_OD_ADDITIONAL
SET 
	DELIVERY_STATUS = #{deliveryStatus}
WHERE OD_JOB_NO = #{odJobNo}
